# ============================================================
# BUILD FUNCTION
# ============================================================
def build():
    print(f"\n{C_CYAN}=== NEXUS-CLIPPER AI ULTRA BUILD ==={C_RESET}\n")
    total = len(FILES)
    print(f"  Generating {total} files to: {BASE_DIR}\n")
    if BASE_DIR.exists():
        shutil.rmtree(BASE_DIR)
    for folder in FOLDERS:
        (BASE_DIR / folder).mkdir(parents=True, exist_ok=True)
    lines_total = 0
    for i, (rel_path, getter) in enumerate(FILES.items(), 1):
        try:
            content = getter if isinstance(getter, str) else getter()
            filepath = BASE_DIR / rel_path
            write_file(str(filepath), content)
            lc = len(content.splitlines())
            lines_total += lc
            progress(f"{rel_path} ({lc} lines)", i, total)
        except Exception as e:
            warn(f"Failed: {rel_path} - {e}")
    # Extra files
    env = "# Nexus-Clipper AI Ultra - .env\nDEBUG=false\nHOST=0.0.0.0\nPORT=8000\n"
    write_file(str(BASE_DIR / ".env.example"), env)
    gitignore = "__pycache__/\n*.pyc\nvenv/\n.env\nnode_modules/\ndist/\noutput/\nlogs/\nmodels/*.pt\n.DS_Store\n"
    write_file(str(BASE_DIR / ".gitignore"), gitignore)
    readme = f"# {PROJECT_NAME} v{PROJECT_VERSION}\n\nAutonomous 25-Agent Video Generation Platform. Zero cost, open source.\n\n## Quick Start\n```bash\npython build_nexus.py\ninstall_nexus.bat  # Windows\ncd backend && uvicorn main:app --reload\ncd frontend && npm install && npm run dev\n```\n"
    write_file(str(BASE_DIR / "README.md"), readme)
    # Copy install_nexus.bat
    src_bat = Path(__file__).parent / "install_nexus.bat"
    if src_bat.exists():
        shutil.copy(src_bat, BASE_DIR / "install_nexus.bat")
    print(f"\n{C_GREEN}=== BUILD COMPLETE: {total} files, {lines_total} lines ==={C_RESET}")
    print(f"  Location: {BASE_DIR}")
    print(f"  Next: cd {PROJECT_SLUG} && install_nexus.bat")

if __name__ == "__main__":
    build()
